keyConcepts.codeExample:
seen_products: set[str] = set()

def has_seen(product_id: str) -> bool:
    return product_id in seen_products  # O(1) au lieu de O(n) avec une liste

def record_view(product_id: str) -> None:
    seen_products.add(product_id)  # les doublons sont éliminés automatiquement

recommendations = [p for p in catalog if p.id not in seen_products]
